pub fn getCPtr(value: JSValue) ?usize {
        if (value.isNumber()) {
            const addr = value.asPtrAddress();
            if ((addr > 0)) {
                return addr;
            }
        } else {
            if (value.isBigInt()) {
                const addr = @as(u64, @bitCast(value.toUInt64NoTruncate()));
                if ((addr > 0)) {
                    return addr;
                }
            }
        }
        return null;
}

